// Mesma lista/ids do array OBRAS em prototipo/index.html -- diferente do
// fluxo de Orçamentos Complementares, aqui NÃO dá pra descobrir as obras a
// partir de 1 chamada só (a API exige `obra_id` por request, sem endpoint
// "lista todas as obras"), então a lista fixa é inevitável. CNPEM -
// Auditório (id 103) fica DE FORA de propósito -- decisão já tomada
// (2026-08-11) de que essa obra não faz parte do painel. Se uma obra nova
// entrar no painel, adicionar aqui também.
const OBRAS = [
  { id: 106, nome: 'CNPEM - Faseado' },
  { id: 110, nome: 'Hitachi' },
  { id: 94,  nome: 'Porto Itapoá' },
  { id: 107, nome: 'Novo Nordisk - AP' },
  { id: 108, nome: 'Novo Nordisk - AP - Reforço' },
  { id: 91,  nome: 'Novo Nordisk - UB/SP' },
];

return OBRAS.map(o => ({ json: { id_obra: o.id, nome_obra: o.nome } }));

// Modo padrão "Run Once for All Items" (não mexer -- é o correto aqui,
// diferente do bug do fluxo de Orçamentos Complementares onde esse modo
// era o ERRADO: lá a saída precisava ser 1-por-1 pareada por pairedItem,
// aqui a saída é um FAN-OUT de 1 item de obra pra N linhas de pedido, que
// é exatamente o que "All Items" resolve bem).
//
// Casa cada resposta HTTP com sua obra de origem por POSIÇÃO (mesma ordem
// de entrada/saída -- garantia padrão do n8n pra nodes não-batch como o
// HTTP Request). Guard explícito: se as contagens não baterem, aborta com
// erro claro em vez de arriscar juntar pedido com obra errada.
const listaObras = $('Lista de obras').all();
const respostas = $input.all();
if (listaObras.length !== respostas.length) {
  throw new Error(`Descompasso entre lista de obras (${listaObras.length}) e respostas HTTP (${respostas.length}) -- abortando pra não misturar pedido com obra errada.`);
}

return respostas.map((resp, i) => {
  const idObra = listaObras[i].json.id_obra;
  const pedidos = Array.isArray(resp.json.data) ? resp.json.data : [];
  const linhas = pedidos.map(p => ({
    id_obra: idObra,
    banco_s1: p.banco_s1 ?? null,
    numero_pedido: p.numero_pedido != null ? String(p.numero_pedido) : null,
    numero_requisicao: p.numero_requisicao || null,
    obra_nome: p.obra || null,
    tipo_descricao: p.tipo_descricao || null,
    status_pedido: p.status_pedido || null,
    solicitante: p.solicitante || null,
    comprador: p.comprador || null,
    fornecedor: p.fornecedor || null,
    fornecedor_cnpj: p.fornecedor_cnpj || null,
    valor: p.valor ?? null,
    valor_liquido: p.valor_liquido ?? null,
    desconto: p.desconto ?? null,
    acrescimo: p.acrescimo ?? null,
    frete: p.frete ?? null,
    data_pedido: p.data_pedido || null,
    data_entrega: p.data_entrega || null,
    entrega_atualizada: p.entrega_atualizada || null,
    descricao: p.descricao || null,
    grupo: p.grupo || null,
    observacoes: p.observacoes || null,
    itens: Array.isArray(p.itens) ? p.itens : [],
    raw: p,
    atualizado_em: new Date().toISOString(),
  }));
  return { json: { id_obra: idObra, linhas } };
});
